CREATE TABLE IF NOT EXISTS services(id VARCHAR(64) PRIMARY KEY,name VARCHAR(200) NOT NULL,price_cents INT UNSIGNED NULL,content TEXT);
CREATE TABLE IF NOT EXISTS pages(slug VARCHAR(180) PRIMARY KEY,content JSON NOT NULL);
CREATE TABLE IF NOT EXISTS admins(id CHAR(36) PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(256) NOT NULL);
CREATE TABLE IF NOT EXISTS admin_sessions(token_hash CHAR(64) PRIMARY KEY,admin_id CHAR(36) NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(admin_id) REFERENCES admins(id));
CREATE TABLE IF NOT EXISTS orders(id CHAR(36) PRIMARY KEY,reference VARCHAR(30) NOT NULL UNIQUE,request_id CHAR(36) NOT NULL UNIQUE,token_hash CHAR(64) NOT NULL,service_id VARCHAR(64) NOT NULL,company VARCHAR(200) NOT NULL,email VARCHAR(254) NOT NULL,phone VARCHAR(30) NOT NULL,profile_url VARCHAR(1500) NOT NULL,keywords TEXT NOT NULL,description TEXT NOT NULL,billing_name VARCHAR(200),billing_nip VARCHAR(10),billing_address VARCHAR(500),status VARCHAR(30) NOT NULL DEFAULT 'nowe',price_cents INT UNSIGNED NULL,payment_status VARCHAR(30) NOT NULL DEFAULT 'not_required',payment_provider_order_id VARCHAR(64),payment_redirect_url VARCHAR(2000),goal TEXT,notes TEXT,attribution JSON,ip_hash CHAR(64),raw_ip VARCHAR(45),user_agent VARCHAR(512),privacy_version VARCHAR(30) NOT NULL,analytics_consent BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),INDEX(status),INDEX(payment_status),INDEX(payment_provider_order_id),INDEX(created_at),FOREIGN KEY(service_id) REFERENCES services(id));
CREATE TABLE IF NOT EXISTS order_history(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id CHAR(36) NOT NULL,status VARCHAR(30) NOT NULL,message TEXT NOT NULL,actor VARCHAR(254) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS mail_outbox(id CHAR(36) PRIMARY KEY,recipient VARCHAR(254) NOT NULL,subject VARCHAR(200) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',attempts INT NOT NULL DEFAULT 0,last_error VARCHAR(300),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status));
CREATE TABLE IF NOT EXISTS analytics_events(id BIGINT AUTO_INCREMENT PRIMARY KEY,session_id CHAR(36) NOT NULL,event VARCHAR(40) NOT NULL,path VARCHAR(300) NOT NULL,attribution JSON,device_hash CHAR(64),ip_hash CHAR(64),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(created_at));
CREATE TABLE IF NOT EXISTS rate_limits(`key` VARCHAR(128) NOT NULL,bucket BIGINT NOT NULL,hits INT NOT NULL,expires_at DATETIME NOT NULL,PRIMARY KEY(`key`,bucket));
CREATE TABLE IF NOT EXISTS visits(id INT AUTO_INCREMENT PRIMARY KEY,ip_address VARCHAR(45) NOT NULL,city VARCHAR(100),region VARCHAR(100),country VARCHAR(100),visit_time VARCHAR(100),keyword VARCHAR(255),gclid VARCHAR(255),search_type VARCHAR(50),company_name VARCHAR(255),company_nip VARCHAR(20),company_regon VARCHAR(20),company_address TEXT,company_phone VARCHAR(50),company_website VARCHAR(500),company_rating DECIMAL(3,1),company_reviews_count INT,place_id VARCHAR(255),company_data JSON,user_agent VARCHAR(512),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(ip_address),INDEX(company_nip),INDEX(created_at));

